def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove any spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and separate the groups of nested parentheses
    groups = []
    current_group = ""
    open_braces = 0

    for char in paren_string:
        if char == "(":
            open_braces += 1
        elif char == ")":
            open_braces -= 1

        current_group += char

        if open_braces == 0:
            groups.append(current_group)
            current_group = ""

    # Step 3: Check each group for balanced parentheses
    for i in range(len(groups)):
        if groups[i].count("(") != groups[i].count(")"):
            return "Unbalanced parentheses in group: " + groups[i]

    # Step 4: Check for nested groups and separate them if necessary
    result = []
    for group in groups:
        if "(" in group[1:-1]:
            nested_groups = separate_paren_groups(group[1:-1])
            for nested_group in nested_groups:
                result.append("(" + nested_group + ")")
        else:
            result.append(group)

    # Step 5: Return the list of separated groups
    return result

